package com.campus.lostfound.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * MatchSuggestion entity representing a scored match generated by the Smart Match engine
 * between a LOST item and a FOUND item.
 */
@Entity
@Table(name = "match_suggestions")
public class MatchSuggestion {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "lost_item_id", nullable = false)
    private Item lostItem;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "found_item_id", nullable = false)
    private Item foundItem;

    @Column(nullable = false)
    private double score; // Score from 0.0 to 100.0

    @Column(nullable = false, columnDefinition = "TEXT")
    private String matchReasons;

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt;

    public MatchSuggestion() {
    }

    public MatchSuggestion(Item lostItem, Item foundItem, double score, String matchReasons) {
        this.lostItem = lostItem;
        this.foundItem = foundItem;
        this.score = score;
        this.matchReasons = matchReasons;
    }

    @PrePersist
    protected void onCreate() {
        this.createdAt = LocalDateTime.now();
    }

    // Getters and Setters
    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Item getLostItem() {
        return lostItem;
    }

    public void setLostItem(Item lostItem) {
        this.lostItem = lostItem;
    }

    public Item getFoundItem() {
        return foundItem;
    }

    public void setFoundItem(Item foundItem) {
        this.foundItem = foundItem;
    }

    public double getScore() {
        return score;
    }

    public void setScore(double score) {
        this.score = score;
    }

    public String getMatchReasons() {
        return matchReasons;
    }

    public void setMatchReasons(String matchReasons) {
        this.matchReasons = matchReasons;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }
}
